import { MODES } from './schema.js';

const PLATFORM_NAMES = { chatgpt: 'ChatGPT', claude: 'Claude', gemini: 'Gemini' };
export const DEFAULT_PART_CHARS = 30000;

function refsLabel(refs) {
  if (!refs?.length) return '';
  const uniq = [...new Set(refs)].slice(0, 6).map(r => `#${r + 1}`);
  return `msg ${uniq.join(', ')}`;
}

function renderItem(item) {
  const tags = [];
  if (item.status !== 'confirmed') tags.push(item.status);
  const refs = refsLabel(item.refs);
  if (refs) tags.push(refs);
  const text = item.text.includes('\n') ? item.text.replace(/\n/g, '\n  ') : item.text;
  return `- ${text}${tags.length ? ` _(${tags.join(' · ')})_` : ''}`;
}

function list(title, items, { skipEmpty } = {}) {
  if (!items?.length) return skipEmpty ? '' : `**${title}:**\n- _Not determined from the conversation._\n`;
  return `**${title}:**\n${items.map(renderItem).join('\n')}\n`;
}

function field(title, value, { skipEmpty } = {}) {
  if (!value) return skipEmpty ? '' : `**${title}:** _Not determined from the conversation._\n`;
  return value.includes('\n') ? `**${title}:**\n\n${value}\n` : `**${title}:** ${value}\n`;
}

function fence(code, language = '') {
  const longest = Math.max(2, ...(code.match(/`+/g) || []).map(s => s.length));
  const ticks = '`'.repeat(longest + 1);
  return `${ticks}${language}\n${code}\n${ticks}`;
}

export function extractionSummary(meta = {}) {
  const ex = meta.extraction || {};
  const platform = PLATFORM_NAMES[meta.platform] || meta.platform || 'unknown platform';
  const lines = [];
  const count = ex.messageCount ?? 0;
  if (ex.complete) {
    lines.push(`Source: ${platform} conversation — ${count} messages extracted; no gaps were detected (only what the page rendered could be read).`);
  } else {
    lines.push(`Source: ${platform} conversation — ${count} messages extracted. **PARTIAL EXTRACTION:** some of the conversation may be missing.`);
    for (const w of ex.warnings || []) lines.push(`- ${w}`);
  }
  const gen = meta.generator || {};
  if (gen.type === 'llm') lines.push(`Generated by: ${gen.provider || 'LLM'}${gen.model ? ` (${gen.model})` : ''}${gen.chunks > 1 ? `, processed in ${gen.chunks} chunks` : ''}.`);
  else lines.push(`Generated by: deterministic extraction (no AI model)${gen.fallbackReason ? ` — ${gen.fallbackReason.replace(/[.\s]+$/, '')}` : ''}. Items tagged _assumption_ were found by keyword matching.`);
  return lines.join('\n');
}

/** Section F: instructions telling the next assistant how to use the handoff. */
export function buildContinuationPrompt(handoff) {
  const ex = handoff.meta?.extraction || {};
  const next = handoff.nextSteps?.next;
  const partial = ex.complete ? '' : ' Note: the extraction was partial, so some earlier details may be missing — ask if something you need is not covered.';
  return [
    `You are continuing an ongoing project from a previous AI conversation. The context handoff below was extracted from that conversation.${partial}`,
    '',
    '1. Read and understand the whole handoff before proposing any change.',
    '2. Continue from the current state described here. Do not start over and do not repeat work that is already completed.',
    '3. Respect the decisions, constraints and user preferences listed. Do not reintroduce approaches marked as rejected.',
    '4. Items tagged "assumption" or "unknown" are unverified — confirm them before relying on them.',
    '5. If you can access the actual project files, inspect them first; the files are the source of truth over this summary.',
    '6. Ask only the clarification questions that are necessary to make progress.',
    next ? `7. Begin with the next pending task: ${next}` : '7. Begin with the latest user request described under "Current task".',
  ].join('\n');
}

function codeBlocksSection(blocks, limit) {
  if (!blocks.length) return '';
  const chosen = limit ? blocks.slice(-limit) : blocks;
  const omitted = blocks.length - chosen.length;
  const parts = chosen.map((b, i) => `**Snippet ${i + 1}** (${b.role || 'message'} message ${b.ref !== undefined ? `#${b.ref + 1}` : ''}${b.language ? `, ${b.language}` : ''})\n\n${fence(b.code, b.language)}`);
  const note = omitted > 0 ? `\n_${omitted} earlier code block(s) not included in this mode. Use Full Handoff to include all of them._\n` : '';
  return `### Relevant code\n\n${parts.join('\n\n')}\n${note}`;
}

function transcriptSection(messages) {
  if (!messages?.length) return '';
  const body = messages.map(m => `#### Message #${m.index + 1} — ${m.role}\n\n${m.text}`).join('\n\n');
  return `## Appendix: conversation transcript (as extracted)\n\n${body}\n`;
}

/**
 * Renders a handoff to paste-ready Markdown.
 * @param {object} handoff coerced handoff
 * @param {{mode?:string, messages?:Array}} opts messages are required for the Full Handoff transcript
 */
export function renderHandoffMarkdown(handoff, opts = {}) {
  const mode = opts.mode || handoff.meta?.mode || 'continue';
  const quick = mode === 'quick';
  const full = mode === 'full';
  const skip = { skipEmpty: quick };
  const p = handoff.project, s = handoff.state, d = handoff.decisions, c = handoff.currentTask, n = handoff.nextSteps, a = handoff.artifacts;
  const title = p.name || handoff.meta?.conversationTitle || 'Project';
  const out = [];

  out.push(`# Context handoff: ${title}`);
  out.push(`_${MODES[mode]?.label || 'Handoff'} · ${handoff.meta?.generatedAt ? new Date(handoff.meta.generatedAt).toISOString().slice(0, 16).replace('T', ' ') + ' UTC' : ''}_`);
  out.push(extractionSummary(handoff.meta));
  out.push(`## Instructions for the next AI assistant\n\n${buildContinuationPrompt(handoff)}`);

  if (handoff.customNotes) out.push(`## Must remember (specified by the user)\n\n${handoff.customNotes}`);

  out.push([
    '## A. Project overview',
    field('Project', p.name, skip),
    field('Purpose', p.purpose, skip),
    field('Problem being solved', p.problem, skip),
    list('Main features', p.features, skip),
    list('Technology stack', p.stack, skip),
    field('Architecture', p.architecture, skip),
    quick ? '' : list('Important files, modules and APIs', p.keyFiles, skip),
  ].filter(Boolean).join('\n'));

  if (!quick) {
    out.push([
      '## B. Current implementation state',
      list('Completed', s.completed),
      list('In progress', s.inProgress),
      list('Not yet implemented', s.notImplemented),
      list('Known bugs and unresolved errors', s.bugs),
      list('Important code changes', s.codeChanges, { skipEmpty: true }),
    ].filter(Boolean).join('\n'));
  }

  out.push([
    '## C. Decisions and constraints',
    list('Decisions made', d.decisions, skip),
    quick ? '' : list('Tried and rejected', d.rejected),
    list('User preferences and requirements', d.preferences, skip),
    list('Constraints that must not be violated', d.constraints, skip),
    quick ? '' : list('Security considerations', d.security, { skipEmpty: true }),
    quick ? '' : list('Dependencies', d.dependencies, { skipEmpty: true }),
  ].filter(Boolean).join('\n'));

  out.push([
    '## D. Current task',
    field('Goal of the latest messages', c.goal),
    field('Where the work stopped', c.stoppedAt),
    quick ? '' : list('Already attempted', c.attempted),
    list('What failed (actual errors)', c.failures, { skipEmpty: quick }),
  ].filter(Boolean).join('\n'));

  out.push([
    '## E. Next steps',
    field('Next concrete action', n.next),
    list('Remaining steps (priority order)', n.remaining, skip),
    quick ? '' : list('Tests still to run', n.tests),
    list('Open questions', n.openQuestions, skip),
  ].filter(Boolean).join('\n'));

  if (!quick) {
    const tech = [];
    if (a.commands.length) tech.push(`### Commands\n\n${fence(a.commands.join('\n'), 'bash')}`);
    if (a.errors.length) tech.push(`### Error messages (verbatim)\n\n${fence(a.errors.join('\n\n'))}`);
    if (a.filePaths.length) tech.push(`### File paths mentioned\n\n${a.filePaths.map(f => `- \`${f}\``).join('\n')}`);
    if (a.urls.length) tech.push(`### URLs mentioned\n\n${a.urls.map(u => `- ${u}`).join('\n')}`);
    const code = codeBlocksSection(a.codeBlocks, full ? 0 : 12);
    if (code) tech.push(code);
    if (tech.length) out.push(`## Technical details\n\n${tech.join('\n\n')}`);
  } else if (a.errors.length) {
    out.push(`## Recent errors\n\n${fence(a.errors.slice(-3).join('\n\n'))}`);
  }

  if (handoff.unknowns?.length) out.push(list('Unknowns', handoff.unknowns).replace(/^\*\*Unknowns:\*\*/, '## Unknowns and assumptions\n'));

  if (full && opts.messages?.length) out.push(transcriptSection(opts.messages));

  return out.filter(Boolean).join('\n\n').replace(/\n{3,}/g, '\n\n').trim() + '\n';
}

// ---------------------------------------------------------------------------
// Splitting large handoffs into numbered parts
// ---------------------------------------------------------------------------

/** Splits Markdown into blocks, keeping fenced code blocks intact. */
function toBlocks(md) {
  const lines = md.split('\n');
  const blocks = [];
  let cur = [];
  let fenceMarker = null;
  const flush = () => { if (cur.length) { blocks.push(cur.join('\n')); cur = []; } };
  for (const line of lines) {
    const fm = line.match(/^(`{3,})/);
    if (fenceMarker) {
      cur.push(line);
      if (fm && fm[1].length >= fenceMarker.length && line.trim() === fm[1]) { fenceMarker = null; flush(); }
      continue;
    }
    if (fm) { flush(); fenceMarker = fm[1]; cur.push(line); continue; }
    if (/^#{1,4} /.test(line)) { flush(); cur.push(line); continue; }
    if (line.trim() === '') { flush(); continue; }
    cur.push(line);
  }
  flush();
  return blocks;
}

/** Splits one oversized block by lines; fenced code is closed and reopened across pieces. */
function splitBlock(block, max) {
  const lines = block.split('\n');
  const fm = lines[0].match(/^(`{3,})(.*)$/);
  const open = fm ? lines[0] : null;
  const close = fm ? fm[1] : null;
  const body = fm ? lines.slice(1, lines[lines.length - 1].trim() === close ? -1 : undefined) : lines;
  const pieces = [];
  let cur = [];
  let size = 0;
  const budget = max - (fm ? open.length + close.length + 40 : 0);
  const push = () => {
    if (!cur.length) return;
    pieces.push(fm ? `${open}\n${cur.join('\n')}\n${close}` : cur.join('\n'));
    cur = []; size = 0;
  };
  for (let line of body) {
    while (line.length > budget) { // pathological single line
      if (cur.length) push();
      cur.push(line.slice(0, budget)); push();
      line = line.slice(budget);
    }
    if (size + line.length + 1 > budget) push();
    cur.push(line); size += line.length + 1;
  }
  push();
  return pieces;
}

/**
 * Splits Markdown into numbered parts no larger than maxChars (plus a small header).
 * Returns [{ index, total, title, headings, content }]. A single part is returned unchanged.
 */
export function splitIntoParts(markdown, maxChars = DEFAULT_PART_CHARS) {
  if (markdown.length <= maxChars) {
    return [{ index: 1, total: 1, headings: [], content: markdown }];
  }
  const blocks = toBlocks(markdown).flatMap(b => (b.length > maxChars ? splitBlock(b, maxChars) : [b]));
  const raw = [];
  let cur = [];
  let size = 0;
  let headings = [];
  let lastHeading = '';
  for (const b of blocks) {
    if (size + b.length + 2 > maxChars && cur.length) {
      raw.push({ body: cur.join('\n\n'), headings });
      cur = []; size = 0; headings = [];
      if (lastHeading && !/^#{1,4} /.test(b)) { cur.push(`${lastHeading} (continued)`); size += lastHeading.length + 14; }
    }
    const h = b.match(/^(#{1,3}) (.+)/);
    if (h) { lastHeading = `${h[1]} ${h[2]}`; if (h[1].length <= 2) headings.push(h[2]); }
    cur.push(b); size += b.length + 2;
  }
  if (cur.length) raw.push({ body: cur.join('\n\n'), headings });

  const total = raw.length;
  return raw.map((r, i) => {
    const index = i + 1;
    const header = `<!-- Context handoff part ${index} of ${total} -->\n**Context handoff — part ${index} of ${total}.** ${index < total ? `Reply only "Received part ${index}/${total}" and wait for the next part.` : 'This is the final part: you now have the full handoff, so follow the instructions from part 1.'}`;
    return { index, total, headings: r.headings, content: `${header}\n\n${r.body}\n` };
  });
}

/** Master index describing how the parts fit together. */
export function buildPartsIndex(parts, title = 'Project') {
  const lines = [
    `# Context handoff index: ${title}`,
    '',
    `This handoff is split into ${parts.length} parts because it is too long for a single message. Paste them in order into the new conversation.`,
    '',
    ...parts.map(p => `- **Part ${p.index}/${p.total}:** ${p.headings.length ? p.headings.join('; ') : 'continuation of the previous section'}`),
    '',
    'Part 1 contains the instructions for the next AI assistant. The assistant should acknowledge each part and only start working after the final part.',
  ];
  return lines.join('\n') + '\n';
}
